style.css:
@-moz-document domain("wattpad.com") {
/* page background */
    body {
        background: url("https://i.pinimg.com/564x/c4/07/a4/c407a4d20ba76a2b6e3ac1039da5f779.jpg") repeat fixed;
        background-size: auto;          /* keeps pattern natural size */
        background-color: #d2bfa0;      /* soft beige fallback */
    }

    /* optional: soften main containers so the pattern shows through */
    #app, .page, .container {
        background: rgba(255, 255, 255, 0.85) !important;
    }
}
